package org.example.migration;

import spoon.Launcher;
import spoon.processing.AbstractProcessor;
import spoon.reflect.code.CtInvocation;
import spoon.reflect.code.CtExpression;
import spoon.reflect.reference.CtTypeReference;
import spoon.reflect.factory.Factory;
import spoon.support.sniper.SniperJavaPrettyPrinter;

public class JRPenRefactoring {

    public static class JRPenProcessor extends AbstractProcessor<CtInvocation<?>> {
        @Override
        public boolean isToBeProcessed(CtInvocation<?> candidate) {
            // 1. Name Check
            if (!"setLineWidth".equals(candidate.getExecutable().getSimpleName())) {
                return false;
            }

            // 2. Argument Count Check
            if (candidate.getArguments().size() != 1) {
                return false;
            }

            // 3. Type Check (Defensive for NoClasspath)
            CtExpression<?> arg = candidate.getArguments().get(0);
            CtTypeReference<?> type = arg.getType();

            // Check if argument is already explicitly boxed (Float.valueOf or new Float)
            if (arg instanceof CtInvocation) {
                CtInvocation<?> argInv = (CtInvocation<?>) arg;
                String method = argInv.getExecutable().getSimpleName();
                String declarer = argInv.getExecutable().getDeclaringType() != null 
                    ? argInv.getExecutable().getDeclaringType().getSimpleName() 
                    : "";
                if (("valueOf".equals(method) && "Float".equals(declarer))) {
                    return false;
                }
            }

            // If we know the type is already the wrapper Float, skip.
            // Note: In NoClasspath, type might be null.
            if (type != null && "java.lang.Float".equals(type.getQualifiedName())) {
                return false;
            }

            // 4. Owner Check (Relaxed string matching for inheritance/NoClasspath)
            CtTypeReference<?> owner = candidate.getExecutable().getDeclaringType();
            if (owner != null) {
                String ownerName = owner.getQualifiedName();
                // Match JRPen or JRBasePen (base implementation)
                if (!ownerName.contains("JRPen") && !ownerName.contains("JRBasePen") && !ownerName.equals("<unknown>")) {
                    return false;
                }
            }

            return true;
        }

        @Override
        public void process(CtInvocation<?> invocation) {
            Factory factory = getFactory();
            CtExpression<?> originalArg = invocation.getArguments().get(0);

            // Strategy: The float primitive method was removed.
            // The Float wrapper method remains. We explicitly box the argument: Float.valueOf(arg)

            CtTypeReference<Float> floatRef = factory.Type().createReference(Float.class);
            CtTypeReference<Float> floatPrimitive = factory.Type().floatPrimitiveType();

            // Create Float.valueOf(originalArg)
            CtInvocation<?> replacement = factory.Code().createInvocation(
                factory.Code().createTypeAccess(floatRef),
                factory.Method().createReference(floatRef, floatRef, "valueOf", floatPrimitive),
                originalArg.clone()
            );

            // Replace the original argument with the boxed version
            originalArg.replace(replacement);

            System.out.println("Refactored setLineWidth at line " + invocation.getPosition().getLine());
        }
    }

    public static void main(String[] args) {
        // Default paths
        String inputPath = "./src/main/java";
        String outputPath = "./src/main/gen";

        Launcher launcher = new Launcher();
        launcher.addInputResource(inputPath);
        launcher.setSourceOutputDirectory(outputPath);

        // CRITICAL SETTINGS for Spoon 11+ / Robust Refactoring
        // 1. Enable comments
        launcher.getEnvironment().setCommentEnabled(true);
        // 2. Force Sniper Printer manually to preserve formatting/indentation
        launcher.getEnvironment().setPrettyPrinterCreator(
            () -> new SniperJavaPrettyPrinter(launcher.getEnvironment())
        );
        // 3. Defensive mode for missing dependencies
        launcher.getEnvironment().setNoClasspath(true);

        launcher.addProcessor(new JRPenProcessor());

        try {
            launcher.run();
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}
